import {useEffect,useRef,useState} from 'react';
import type {FormEvent,ReactNode} from 'react';
import type {SupabaseClient} from '@supabase/supabase-js';
import {Activity,ArrowDownToLine,ArrowRight,BarChart3,BookOpen,CalendarDays,Check,CheckCircle2,ChevronLeft,ChevronRight,Clock3,ExternalLink,FileText,Flame,FolderOpen,Globe2,History,Image,Layers3,LayoutDashboard,Link2,LoaderCircle,LogOut,Menu,Plus,RefreshCw,Search,Settings2,ShieldCheck,Sparkles,Trash2,Upload,Users,WandSparkles,X,Zap} from 'lucide-react';
import type {LucideIcon} from 'lucide-react';
import type {Workspace,PostData,RecordRow,SourceData,Role,Platform,Blog} from '../../src/contracts';
import {platformNames,statusNames,roles} from '../../src/contracts';
import {request,downloadFile,authClient,text,num,obj,arr} from './api';
import type {Dataset,Runtime,GenericRow} from './api';
import {SourceSuggestions} from './SourceSuggestions';
import type {SuggestedTrendSource} from '../../src/engine/source-catalog';

const navigation:{id:string;title:string;icon:LucideIcon}[]=[{id:'overview',title:'Visão geral',icon:LayoutDashboard},{id:'trends',title:'Radar de tendências',icon:Flame},{id:'sources',title:'Biblioteca de fontes',icon:FolderOpen},{id:'studio',title:'Estúdio de criação',icon:WandSparkles},{id:'calendar',title:'Calendário',icon:CalendarDays},{id:'analytics',title:'Resultados',icon:BarChart3},{id:'settings',title:'Configurações',icon:Settings2}];
const platforms=Object.keys(platformNames) as Platform[];
const roleNames:Record<Role,string>={admin:'Administrador',editor:'Editor',reviewer:'Revisor',publisher:'Publicador',viewer:'Leitor'};
const structureNames=['Problema → descoberta → solução','Notícia → contexto → análise','Mito → evidência → conclusão','Lista prática → exemplos → ação','História → aprendizado → convite'];
const emptyBlog:Blog={url:'',status:'undefined',platform:'',feedUrl:'',language:'pt-BR',integrationState:'not_configured'};
const defaults={name:'',niche:'',audience:'',objectives:'',timezone:'America/Sao_Paulo',brand:{color:'#173b2c',voice:''},blog:emptyBlog};
const numeric=(n:number|null)=>n===null?'—':new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1,notation:n>=10000?'compact':'standard'}).format(n);
const initials=(n:string)=>n.split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();
function dateLabel(v:string,zone='America/Sao_Paulo',time=false){const d=new Date(v);return Number.isNaN(d.getTime())?'Sem data':d.toLocaleString('pt-BR',{day:'2-digit',month:'short',...(time?{hour:'2-digit',minute:'2-digit'}:{}),timeZone:zone});}
function stateLabel(v:unknown){const labels:Record<string,string>={recent_opportunity:'Oportunidade recente',decelerating:'Em desaceleração',queued:'Na fila',processing:'Em processamento',succeeded:'Concluído',failed:'Falhou',uncertain:'Reconciliação pendente',cancelled:'Cancelado',published:'Publicado',connected:'Conectada',expired:'Expirada',revoked:'Revogada',active:'Ativa',pending:'Pendente',extracted:'Extraído',metadata_only:'Somente metadados',not_configured:'Não configurado',insufficient_data:'Histórico insuficiente',growing:'Em crescimento',recent:'Oportunidade recente',observing:'Em observação',stable:'Estável',declining:'Em desaceleração',saved:'Salva',discarded:'Descartada'};return labels[text(v)]??text(v,'Indisponível');}
function Blank({icon:Icon=Layers3,title,children,action}:{icon?:LucideIcon;title:string;children:ReactNode;action?:ReactNode}){return <div className="empty"><span><Icon size={25}/></span><h3>{title}</h3><p>{children}</p>{action}</div>;}
function Badge({children,tone='neutral'}:{children:ReactNode;tone?:string}){return <span className={`badge ${tone}`}>{children}</span>;}
function PostStatus({status}:{status:PostData['status']}){return <Badge tone={status==='approved'?'success':status==='in_review'?'purple':status==='changes_requested'?'warning':'neutral'}>{statusNames[status]}</Badge>;}
function Network({name}:{name:Platform}){return <span className={`network ${name}`} title={platformNames[name]}>{name==='instagram'?'◎':name==='facebook'?'f':name==='linkedin'?'in':name==='youtube'?'▶':'♪'}</span>;}
function Modal({title,children,close,wide=false}:{title:string;children:ReactNode;close:()=>void;wide?:boolean}){const ref=useRef<HTMLDivElement>(null);const closeRef=useRef(close);closeRef.current=close;
  useEffect(()=>{const previous=document.activeElement as HTMLElement|null;ref.current?.focus();const listener=(e:KeyboardEvent)=>{if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const els=ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled),a[href]');if(!els?.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===ref.current)){e.preventDefault();first.focus();}}};document.addEventListener('keydown',listener);const overflow=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',listener);document.body.style.overflow=overflow;previous?.focus();};},[]);
  return <div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)close();}}><div ref={ref} tabIndex={-1} role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide?'wide':''}`}><div className="modal-title"><h2>{title}</h2><button className="icon" aria-label="Fechar" onClick={close}><X size={22}/></button></div>{children}</div></div>;
}
function Section({title,subtitle,children,action}:{title:string;subtitle?:string;children:ReactNode;action?:ReactNode}){return <section className="panel"><div className="section-heading"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{children}</section>;}

export default function App(){
  const [runtime,setRuntime]=useState<Runtime|null>(null),[token,setToken]=useState(''),[client,setClient]=useState<SupabaseClient|null>(null);
  const [page,setPage]=useState('overview'),[workspaces,setWorkspaces]=useState<Workspace[]>([]),[tenant,setTenant]=useState(''),[dataset,setDataset]=useState<Dataset|null>(null);
  const [loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[mobile,setMobile]=useState(false);
  const [modal,setModal]=useState<'workspace'|'source'|'trendSource'|'history'|null>(null),[editing,setEditing]=useState<RecordRow<PostData>|null>(null),[historyPost,setHistoryPost]=useState<RecordRow<PostData>|null>(null);
  const [suggestion,setSuggestion]=useState<SuggestedTrendSource|null>(null);
  const [search,setSearch]=useState(''),[postFilter,setPostFilter]=useState('all'),[range,setRange]=useState(30),[network,setNetwork]=useState('all');
  const generation=useRef(0),tenantRef=useRef(''),abort=useRef<AbortController|null>(null);tenantRef.current=tenant;
  const workspace=dataset?.workspace??workspaces.find(w=>w.id===tenant);const granted=workspace?.roles??[];
  const can=(...r:Role[])=>granted.includes('admin')||r.some(role=>granted.includes(role));
  const api=<T,>(path:string,body?:unknown,method='POST')=>request<T>(`/api/tenants/${encodeURIComponent(tenant)}/${path}`,token,{method,body:body===undefined?undefined:JSON.stringify(body)});
  useEffect(()=>{let alive=true;request<Runtime>('/api/runtime','').then(r=>{if(!alive)return;setRuntime(r);if(r.sandbox&&r.sandboxToken){setToken(r.sandboxToken);setLoading(false);}else{const c=authClient(r);setClient(c);if(c)c.auth.getSession().then(({data,error:e})=>{if(!alive)return;if(e)setError(e.message);setToken(data.session?.access_token??'');setLoading(false);});else setLoading(false);}}).catch(e=>{if(alive){setError(e.message);setLoading(false);}});return()=>{alive=false;};},[]);
  useEffect(()=>{if(!client)return;const {data}=client.auth.onAuthStateChange((_event,session)=>{generation.current++;abort.current?.abort();setDataset(null);setWorkspaces([]);setTenant('');setEditing(null);setToken(session?.access_token??'');});return()=>data.subscription.unsubscribe();},[client]);
  async function loadWorkspaces(select?:string){const t=token;const r=await request<{workspaces:Workspace[]}>('/api/workspaces',t);setWorkspaces(r.workspaces);setTenant(old=>select??(r.workspaces.some(w=>w.id===old)?old:r.workspaces[0]?.id??''));}
  useEffect(()=>{if(!token)return;let alive=true;setLoading(true);request<{workspaces:Workspace[]}>('/api/workspaces',token).then(r=>{if(alive){setWorkspaces(r.workspaces);setTenant(r.workspaces[0]?.id??'');}}).catch(e=>{if(alive)setError(e.message);}).finally(()=>{if(alive)setLoading(false);});return()=>{alive=false;};},[token]);
  async function refresh(){if(!tenant)return;const target=tenant;const current=++generation.current;abort.current?.abort();const controller=new AbortController();abort.current=controller;setLoading(true);try{const r=await request<Dataset>(`/api/tenants/${encodeURIComponent(target)}/dataset`,token,{signal:controller.signal});if(current===generation.current&&target===tenantRef.current){setDataset(r);setWorkspaces(ws=>ws.map(w=>w.id===target?r.workspace:w));setError('');}}catch(e){if(current===generation.current&&(e as Error).name!=='AbortError')setError((e as Error).message);}finally{if(current===generation.current)setLoading(false);}}
  useEffect(()=>{setDataset(null);setEditing(null);setHistoryPost(null);setSearch('');setPostFilter('all');setModal(null);if(tenant)void refresh();return()=>{generation.current++;abort.current?.abort();};},[tenant,token]);
  useEffect(()=>{document.title=`${navigation.find(n=>n.id===page)?.title??'Painel'} · SocialEngine`;},[page]);
  useEffect(()=>{if(!notice)return;const t=setTimeout(()=>setNotice(''),6000);return()=>clearTimeout(t);},[notice]);
  async function action(fn:()=>Promise<unknown>,message='Alteração salva.'){const target=tenant;setBusy(true);setError('');try{await fn();if(target===tenantRef.current){setNotice(message);await refresh();}}catch(e){if(target===tenantRef.current)setError((e as Error).message);}finally{setBusy(false);}}
  function go(id:string){setPage(id);setMobile(false);setSearch('');window.scrollTo({top:0,behavior:'instant'});}
  function newPost(){if(!workspace){setModal('workspace');return;}setEditing({id:'',tenantId:tenant,kind:'post',revision:0,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),data:{title:'',format:'carousel',slides:[{id:crypto.randomUUID(),title:'',body:''}],caption:'',cta:'',sourceIds:[],structure:structureNames[0],color:workspace.brand.color,platforms:['instagram'],status:'draft'}});}
  async function savePost(row:RecordRow<PostData>){const target=tenant;const clean={...row.data,referenceUrl:row.data.referenceUrl||undefined};const body=row.id?{revision:row.revision,data:clean}:clean;const result=await api<{post:RecordRow<PostData>}>(row.id?`posts/${row.id}`:'posts',body,row.id?'PUT':'POST');if(target===tenantRef.current){setEditing(result.post);await refresh();}return result.post;}
  async function review(row:RecordRow<PostData>,decision:'submit'|'approve'|'request_changes',comment?:string){await action(async()=>{const r=await api<{post:RecordRow<PostData>}>(`posts/${row.id}/review`,{revision:row.revision,action:decision,comment});if(editing?.id===row.id)setEditing(r.post);},'Decisão de revisão registrada.');}
  async function logout(){generation.current++;abort.current?.abort();setDataset(null);setWorkspaces([]);setTenant('');setEditing(null);if(client)await client.auth.signOut();setToken('');}
  const headerAction=<button className="primary" onClick={newPost} disabled={!can('editor')}><Plus size={17}/> Criar conteúdo</button>;
  if(!runtime)return <main className="login"><Brand/><div className="panel login-panel">{loading?<><LoaderCircle className="spin"/><h1>Preparando seu espaço</h1></>:<><h1>Não foi possível iniciar</h1><p role="alert">{error}</p><button onClick={()=>location.reload()}>Tentar novamente</button></>}</div></main>;
  if(!token)return <main className="login"><Brand/><div className="login-columns"><div><span className="eyebrow">DO INSIGHT À PUBLICAÇÃO</span><h1>Suas ideias.<br/>Seu próximo<br/><em>grande conteúdo.</em></h1><p>Um espaço para descobrir tendências, criar com identidade e acompanhar o que acontece depois de publicar.</p><div className="login-proof"><ShieldCheck/> Dados separados por influenciador</div></div><div className="panel login-panel"><h2>Entre no SocialEngine</h2><p>Acesse os espaços vinculados à sua conta.</p>{error&&<div className="alert" role="alert">{error}</div>}{!runtime.authConfigured?<><div className="pending"><ShieldCheck/><p>O acesso ainda depende da configuração de identidade da plataforma.</p></div>{runtime.blockers?.map((b,i)=><p className="muted" key={i}>{b}</p>)}</>:<form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);setBusy(true);setError('');try{if(!client)throw new Error('Autenticação indisponível.');const {error:e}=await client.auth.signInWithPassword({email:String(f.get('email')),password:String(f.get('password'))});if(e)throw e;}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}><label>E-mail<input type="email" name="email" required autoComplete="username"/></label><label>Senha<input type="password" name="password" required autoComplete="current-password"/></label><button className="primary full" disabled={busy}>{busy?<LoaderCircle className="spin" size={17}/>:<ArrowRight size={17}/>} Entrar</button></form>}</div></div></main>;
  return <div className="app"><a href="#main" className="skip-link">Pular para o conteúdo</a>{mobile&&<button className="nav-overlay" aria-label="Fechar menu" onClick={()=>setMobile(false)}/>}
    <aside className={`sidebar ${mobile?'open':''}`}><Brand/><div className="workspace-picker"><span className="avatar">{initials(workspace?.name??'SE')}</span><label><span>ESPAÇO ATIVO</span><select aria-label="Selecionar influenciador" value={tenant} onChange={e=>{setDataset(null);setTenant(e.target.value);setEditing(null);}}><option value="" disabled>Selecione um espaço</option>{workspaces.map(w=><option key={w.id} value={w.id}>{w.name}</option>)}</select></label></div><button className="new-workspace" onClick={()=>setModal('workspace')}><Plus size={14}/> Novo influenciador</button><div className="nav-label">SEU MOTOR DE CONTEÚDO</div><nav aria-label="Navegação principal">{navigation.map(n=><button key={n.id} className={page===n.id?'active':''} onClick={()=>go(n.id)}><n.icon size={19}/>{n.title}{n.id==='trends'&&<span className="nav-dot"/>}</button>)}</nav><div className="sidebar-bottom"><div className="sidebar-note"><Zap size={20}/><p>Da ideia ao impacto.<br/><strong>Com a sua identidade.</strong></p></div><div className="session"><span className="mini-avatar"><Users size={17}/></span><div><strong>{runtime.sandbox?'Sandbox local':'Sessão autenticada'}</strong><small>{granted.map(r=>roleNames[r]).join(' · ')||'Selecione um espaço'}</small></div>{!runtime.sandbox&&<button className="icon" aria-label="Sair" onClick={()=>void logout()}><LogOut size={16}/></button>}</div></div></aside>
    <div className="shell"><header className="topbar"><div className="breadcrumbs"><button className="icon mobile-toggle" aria-label="Abrir menu" onClick={()=>setMobile(true)}><Menu/></button><span>Seu espaço</span><ChevronRight size={14}/><strong>{navigation.find(n=>n.id===page)?.title}</strong></div><div className="top-actions"><span className="privacy"><ShieldCheck size={14}/> Espaço privado</span><button className="icon" aria-label="Atualizar dados" disabled={loading||!tenant} onClick={()=>void refresh()}><RefreshCw size={17} className={loading?'spin':''}/></button><span className="mini-avatar">{initials(workspace?.name??'SE')}</span></div></header>
    {runtime.sandbox&&<div className="sandbox"><ShieldCheck size={15}/><strong>Sandbox local</strong><span>Dados de teste isolados. Publicação e métricas reais dependem de integrações autorizadas.</span></div>}
    <main id="main" tabIndex={-1}><div className="page-title"><div><span className="eyebrow">{workspace?.name??'SOCIALENGINE'} · {workspace?.niche||'SEU MOTOR DE CONTEÚDO'}</span><h1>{page==='overview'?<>Bom conteúdo começa<br className="desktop-break"/> com uma boa <em>direção.</em></>:navigation.find(n=>n.id===page)?.title}</h1><p>{({overview:'Acompanhe seu espaço, encontre oportunidades e faça suas ideias acontecerem.',trends:'Sinais reais, contexto e evidências para escolher a próxima pauta.',sources:'O ponto de partida do seu conteúdo, com origem e histórico.',studio:'Transforme referências em conteúdo original com a sua identidade.',calendar:'Planeje o ritmo. Acompanhe cada destino.',analytics:'Resultados com contexto, origem e histórico.',settings:'Uma identidade própria. Conexões e preferências no seu controle.'} as Record<string,string>)[page]}</p></div>{page==='sources'?<button className="primary" disabled={!can('editor')} onClick={()=>setModal('source')}><Plus size={17}/> Adicionar fonte</button>:page==='trends'?<button className="primary" disabled={!can('editor')} onClick={()=>{setSuggestion(null);setModal('trendSource');}}><Plus size={17}/> Monitorar fonte</button>:headerAction}</div>
    {error&&<div className="alert" role="alert"><span>{error}</span><button className="icon" onClick={()=>setError('')} aria-label="Dispensar erro"><X size={16}/></button></div>}
    {notice&&<div className="toast" role="status"><CheckCircle2 size={18}/>{notice}</div>}
    {runtime.blockers?.length>0&&<details className="blockers"><summary>{runtime.blockers.length} dependência(s) da plataforma aguardando configuração</summary><ul>{runtime.blockers.map((b,i)=><li key={i}>{b}</li>)}</ul></details>}
    {!tenant?<Section title="Seu primeiro influenciador"><Blank icon={Users} title="Vamos abrir um novo espaço" action={<button className="primary" onClick={()=>setModal('workspace')}><Plus size={17}/> Cadastrar influenciador</button>}>Cada influenciador tem suas fontes, marca, blog, conteúdos e resultados.</Blank></Section>:loading&&!dataset?<div className="loading" role="status"><LoaderCircle className="spin"/><p>Carregando o espaço selecionado…</p></div>:!dataset?<Blank title="Dados indisponíveis" action={<button onClick={()=>void refresh()}>Tentar novamente</button>}>Não foi possível carregar este espaço.</Blank>:<>
    {(page==='overview'||page==='analytics')&&<Filters range={range} setRange={setRange} network={network} setNetwork={setNetwork}/>}
    {page==='overview'&&<Dashboard data={dataset} range={range} network={network} go={go} edit={setEditing} newPost={newPost} canEdit={can('editor')}/>}
    {page==='analytics'&&<Analytics data={dataset} range={range} network={network} token={token}/>}
    {page==='studio'&&<><div className="list-filters"><div className="search"><Search size={17}/><input aria-label="Buscar conteúdos" placeholder="Buscar um conteúdo…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select aria-label="Filtrar por status" value={postFilter} onChange={e=>setPostFilter(e.target.value)}><option value="all">Todos os estados</option>{Object.entries(statusNames).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></div><div className="post-grid">{dataset.posts.filter(p=>(postFilter==='all'||p.data.status===postFilter)&&p.data.title.toLowerCase().includes(search.toLowerCase())).map(p=><PostCard key={p.id} post={p} open={()=>setEditing(p)} history={()=>{setHistoryPost(p);setModal('history');}}/>)}</div>{!dataset.posts.length&&<Blank icon={WandSparkles} title="O próximo post começa aqui" action={headerAction}>Escolha suas fontes, defina uma estrutura e crie seu primeiro conteúdo.</Blank>}</>}
    {page==='sources'&&<SourceList sources={dataset.sources} token={token} tenant={tenant}/>}
    {page==='trends'&&<Trends key={tenant} suggest={source=>{setSuggestion(source);setModal('trendSource');}} data={dataset} api={api} action={action} canEdit={can('editor')} canAdmin={can('admin')} busy={busy} edit={setEditing}/>}
    {page==='calendar'&&<Calendar data={dataset} api={api} action={action} edit={setEditing} canPublish={can('publisher')}/>}
    {page==='settings'&&<Settings key={tenant} workspace={dataset.workspace} data={dataset} api={api} action={action} busy={busy} admin={can('admin')}/>}
    </>}
    <footer><Brand small/><span>Crie com intenção. Publique com confiança.</span><span>{workspace?.timezone??'America/Sao_Paulo'}</span></footer></main></div>
    {modal==='workspace'&&<Modal title="Cadastrar influenciador" close={()=>setModal(null)}><WorkspaceForm submit={async values=>{await action(async()=>{const r=await request<{workspace:Workspace}>('/api/workspaces',token,{method:'POST',body:JSON.stringify(values)});await loadWorkspaces(r.workspace.id);setModal(null);},'Influenciador cadastrado.');}} busy={busy}/></Modal>}
    {modal==='source'&&<Modal title="Adicionar material-fonte" close={()=>setModal(null)}><SourceForm busy={busy} submit={async(values,file)=>{await action(async()=>{let fileId:string|undefined;if(file){const f=new FormData();f.set('file',file);const upload=await request<{file:{id:string}}>(`/api/tenants/${tenant}/files`,token,{method:'POST',body:f});fileId=upload.file.id;}await api('sources',{...values,fileId});setModal(null);},'Fonte salva. O estado de extração está na biblioteca.');}}/></Modal>}
    {modal==='trendSource'&&<Modal title="Monitorar uma fonte" close={()=>setModal(null)}><TrendSourceForm initial={suggestion} busy={busy} submit={values=>action(async()=>{await api('trend-sources',values);setModal(null);},'Fonte de monitoramento cadastrada.')}/></Modal>}
    {modal==='history'&&historyPost&&<Modal title={`Histórico · ${historyPost.data.title}`} close={()=>setModal(null)}><p>Versões preservadas e decisões de revisão deste conteúdo.</p><div className="history-list">{dataset?.versions.filter(v=>text(v.data.postId)===historyPost.id).map(v=><details key={v.id}><summary>Versão {text(v.data.revision,v.revision.toString())} · {dateLabel(v.createdAt,workspace?.timezone,true)}</summary><pre>{JSON.stringify(v.data,null,2)}</pre></details>)}</div>{!dataset?.versions.some(v=>text(v.data.postId)===historyPost.id)&&<p className="muted">Ainda não há versões anteriores disponíveis.</p>}{dataset?.audit.filter(a=>a.resourceId===historyPost.id).map(a=><div className="activity" key={a.id}><History size={15}/><div><strong>{a.action}</strong><small>{dateLabel(a.createdAt,workspace?.timezone,true)}</small></div></div>)}</Modal>}
    {editing&&dataset&&<Modal title={editing.id?'Estúdio de criação':'Novo conteúdo'} close={()=>setEditing(null)} wide><Editor key={`${tenant}:${editing.id||'new'}`} row={editing} data={dataset} busy={busy} canEdit={can('editor')} canReview={can('reviewer')} canPublish={can('publisher')} token={token} api={api} action={action} save={savePost} review={review} update={setEditing}/></Modal>}
  </div>;
}

function PrivateImage({token,tenant,id}:{token:string;tenant:string;id:string}){const [url,setUrl]=useState(''),[failed,setFailed]=useState(false);useEffect(()=>{const controller=new AbortController();let local='';setUrl('');setFailed(false);fetch(`/api/tenants/${tenant}/files/${id}`,{headers:{Authorization:`Bearer ${token}`},signal:controller.signal,cache:'no-store'}).then(async r=>{if(!r.ok||!r.headers.get('content-type')?.startsWith('image/'))throw new Error('Imagem indisponível');const blob=await r.blob();if(controller.signal.aborted)return;local=URL.createObjectURL(blob);setUrl(local);}).catch(e=>{if(e.name!=='AbortError')setFailed(true);});return()=>{controller.abort();if(local)URL.revokeObjectURL(local);};},[token,tenant,id]);return url?<img className="slide-image" src={url} alt="Imagem escolhida para o slide"/>:failed?<span className="image-unavailable">Prévia da imagem indisponível.</span>:<span className="image-unavailable">Carregando imagem privada…</span>;}
function Brand({small=false}:{small?:boolean}){return <div className={`brand ${small?'small':''}`}><span><Zap size={small?16:23} fill="currentColor"/></span><strong>Social<span>Engine</span></strong>{!small&&<sup>●</sup>}</div>;}
function Filters({range,setRange,network,setNetwork}:{range:number;setRange:(v:number)=>void;network:string;setNetwork:(v:string)=>void}){return <div className="filters"><span><Activity size={15}/> Visão do seu espaço</span><div><label><Globe2 size={15}/><select aria-label="Rede dos resultados" value={network} onChange={e=>setNetwork(e.target.value)}><option value="all">Todas as redes</option>{platforms.map(p=><option key={p} value={p}>{platformNames[p]}</option>)}</select></label><label><CalendarDays size={15}/><select aria-label="Período analítico" value={range} onChange={e=>setRange(Number(e.target.value))}><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option><option value="90">Últimos 90 dias</option><option value="365">Últimos 12 meses</option></select></label></div></div>;}

function latestMetrics(data:Dataset,range:number,network:string){const start=Date.now()-range*86400000;const rows=new Map<string,GenericRow>();for(const row of data.metrics){const d=row.data;const observed=Date.parse(text(d.observedAt,row.createdAt));if(observed<start||!Number.isFinite(observed)||(network!=='all'&&d.platform!==network))continue;const key=`${text(d.publicationId,text(d.postId,row.id))}:${text(d.platform)}:${text(d.metric)}:${text(d.unit)}:${text(d.window)}`;const previous=rows.get(key);if(!previous||observed>Date.parse(text(previous.data.observedAt,previous.createdAt)))rows.set(key,row);}return [...rows.values()];}
function aggregate(rows:GenericRow[],field:string){let total:number|null=null;for(const r of rows){const values=obj(r.data.values??r.data.metrics);const v=num(r.data[field])??num(values[field])??(r.data.metric===field?num(r.data.value):null);if(v!==null)total=(total??0)+v;}return total;}
function Dashboard({data,range,network,go,edit,newPost,canEdit}:{data:Dataset;range:number;network:string;go:(v:string)=>void;edit:(p:RecordRow<PostData>)=>void;newPost:()=>void;canEdit:boolean}){
  const metrics=latestMetrics(data,range,network);const start=Date.now()-range*86400000;const publications=data.publications.filter(p=>(network==='all'||p.data.platform===network)&&Date.parse(text(p.data.publishedAt,p.createdAt))>=start&&(p.data.state??p.data.status)==='published');
  const usage=data.usage.filter(r=>Date.parse(r.createdAt)>=start);const tokens=usage.reduce<number|null>((n,r)=>{const v=num(r.data.totalTokens)??num(r.data.tokens);return v===null?n:(n??0)+v;},null);
  const cards=[{label:'Alcance por publicação',value:aggregate(metrics,'reach'),caption:'Soma por post · não são pessoas únicas',icon:Globe2},{label:'Visualizações',value:aggregate(metrics,'views'),caption:'Última observação disponível no período',icon:Activity},{label:'Salvamentos',value:aggregate(metrics,'saves'),caption:'Conforme disponibilidade das redes',icon:BookOpen},{label:'Publicações confirmadas',value:publications.length,caption:`Confirmações nos últimos ${range} dias`,icon:CheckCircle2}];
  const queued=data.jobs.filter(j=>['queued','processing','uncertain','failed'].includes(j.state));
  return <><div className="metric-grid">{cards.map(c=><button className="metric-card" key={c.label} onClick={()=>go('analytics')}><div><span>{c.label}</span><c.icon size={19}/></div><strong>{numeric(c.value)}</strong><small>{c.caption}</small></button>)}</div>
  <div className="dashboard-grid"><Section title="Seu conteúdo, em movimento" subtitle="Produção editorial · estado atual" action={<button className="text-button" onClick={()=>go('studio')}>Abrir estúdio <ArrowRight size={15}/></button>}><div className="pipeline">{(['draft','in_review','approved'] as const).map((s,i)=><button key={s} onClick={()=>go('studio')}><span className={`pipeline-dot dot-${i}`}/><strong>{data.posts.filter(p=>p.data.status===s).length}</strong><small>{statusNames[s]}</small></button>)}</div><div className="recent-posts">{data.posts.slice(0,3).map(p=><button className="content-row" key={p.id} onClick={()=>edit(p)}><div className="post-thumb" style={{background:p.data.color}}><Layers3 size={18}/></div><div><strong>{p.data.title||'Sem título'}</strong><small>{p.data.slides.length} slides · {dateLabel(p.updatedAt,data.workspace.timezone)}</small></div><PostStatus status={p.data.status}/><ChevronRight size={16}/></button>)}{!data.posts.length&&<Blank icon={WandSparkles} title="Abra espaço para a próxima ideia" action={<button disabled={!canEdit} onClick={newPost}>Criar conteúdo</button>}>Seus rascunhos e revisões aparecem aqui.</Blank>}</div></Section>
  <section className="radar-feature"><span className="feature-icon"><Flame size={22}/></span><span className="eyebrow">SEU RADAR ESTÁ AQUI</span><h2>Encontre a pauta.<br/>Crie a sua <em>perspectiva.</em></h2><p>Fontes, sinais e contexto do seu nicho para você decidir o que merece virar conteúdo.</p><div className="radar-count"><strong>{data.trends.length}</strong><span>oportunidades registradas</span></div><button className="dark-button" onClick={()=>go('trends')}>Explorar tendências <ArrowRight size={17}/></button></section>
  <Section title="Próximos passos" subtitle="Fila persistente e planejamento" action={<button className="text-button" onClick={()=>go('calendar')}>Calendário <ArrowRight size={15}/></button>}>{queued.slice(0,4).map(j=><div className="activity" key={j.id}><Clock3 size={18}/><div><strong>{text(obj(j.payload).title,j.type)}</strong><small>{dateLabel(j.runAt,data.workspace.timezone,true)} · {stateLabel(j.state)}</small>{j.lastError&&<small className="danger-text">{j.lastError}</small>}</div></div>)}{!queued.length&&<div className="inline-empty"><CalendarDays size={24}/><p>A programação está livre.<br/><small>Agende uma versão aprovada no estúdio.</small></p></div>}</Section>
  <Section title="Conexões e consumo" subtitle="Saúde das integrações deste influenciador" action={<button className="icon" aria-label="Abrir configurações" onClick={()=>go('settings')}><Settings2 size={17}/></button>}><div className="connection-icons">{platforms.map(p=>{const account=data.accounts.find(a=>a.data.platform===p);return <button key={p} onClick={()=>go('settings')} title={`${platformNames[p]}: ${stateLabel(account?.data.state??'not_configured')}`}><Network name={p}/><span>{platformNames[p]}</span><i className={account?.data.state==='connected'?'connected':''}/></button>;})}</div><div className="usage-row"><span><Sparkles size={16}/> Uso de IA no período</span><strong>{numeric(tokens)} <small>tokens</small></strong></div><p className="micro">Custo e saldo aparecem quando disponibilizados pelo provedor e pela cota do espaço.</p></Section>
  <Section title="Atividade recente" subtitle="Histórico de alterações deste espaço"><div className="activity-list">{data.audit.slice(0,5).map(a=><div className="activity" key={a.id}><span className="activity-dot"/><div><strong>{a.action}</strong><small>{dateLabel(a.createdAt,data.workspace.timezone,true)} · {text(a.metadata.actorId,'Servidor')}</small></div></div>)}{!data.audit.length&&<p className="muted">Nenhuma atividade registrada.</p>}</div></Section>
  <Section title="Oportunidades em observação" subtitle="Evidências primeiro. Decisão editorial depois." action={<button className="text-button" onClick={()=>go('trends')}>Ver radar <ArrowRight size={15}/></button>}>{data.trends.slice(0,3).map(t=><button className="trend-mini" key={t.id} onClick={()=>go('trends')}><Flame size={17}/><div><strong>{text(t.data.title,text(t.data.topic,'Oportunidade'))}</strong><small>{stateLabel(t.data.state)} · {text(t.data.confidence,'Confiança indisponível')}</small></div><ArrowRight size={15}/></button>)}{!data.trends.length&&<div className="inline-empty"><Flame size={25}/><p>Seu radar começa pelas fontes.<br/><button className="text-button" onClick={()=>go('trends')}>Configurar monitoramento <ArrowRight size={13}/></button></p></div>}</Section></div></>;
}

function PostCard({post,open,history}:{post:RecordRow<PostData>;open:()=>void;history:()=>void}){const d=post.data;return <article className="post-card"><button className="post-cover" style={{background:d.color}} onClick={open}><span className="cover-top">{d.format==='video'?'VÍDEO':d.format==='text'?'TEXTO':'CARROSSEL'} <Layers3 size={16}/></span><h2>{d.slides[0]?.title||d.title||'Seu próximo conteúdo'}</h2><span className="cover-bottom">{d.slides.length} slides <ArrowRight size={20}/></span></button><div className="post-card-details"><PostStatus status={d.status}/><button className="icon" aria-label={`Histórico de ${d.title}`} onClick={history}><History size={16}/></button><button className="post-title" onClick={open}>{d.title||'Sem título'}</button><div className="post-meta"><span>{d.platforms.map(p=><Network key={p} name={p}/>)}</span><small>{dateLabel(post.updatedAt)}</small></div></div></article>;}

function SourceList({sources,token,tenant}:{sources:RecordRow<SourceData>[];token:string;tenant:string}){const [filter,setFilter]=useState(''),[error,setError]=useState('');const rows=sources.filter(s=>`${s.data.title} ${s.data.text}`.toLowerCase().includes(filter.toLowerCase()));return <><div className="search"><Search size={17}/><input aria-label="Buscar fontes" placeholder="Buscar na biblioteca…" value={filter} onChange={e=>setFilter(e.target.value)}/></div>{error&&<p className="alert" role="alert">{error}</p>}<div className="source-grid">{rows.map(s=><article className="panel source-card" key={s.id}><div className="source-heading"><span className="source-icon"><FileText size={21}/></span><Badge>{s.data.kind}</Badge></div><h2>{s.data.title}</h2><p>{s.data.text?.slice(0,250)||'O conteúdo ainda não foi extraído. Metadados não substituem a leitura da fonte.'}</p><Badge tone={s.data.extractionState==='extracted'?'success':s.data.extractionState==='failed'?'warning':'neutral'}>{stateLabel(s.data.extractionState)}</Badge>{s.data.error&&<p className="danger-text">{s.data.error}</p>}<div className="source-footer"><small>{dateLabel(s.createdAt)}</small>{s.data.url&&/^https?:\/\//i.test(s.data.url)&&<a href={s.data.url} target="_blank" rel="noreferrer">Abrir origem <ExternalLink size={13}/></a>}{s.data.fileId&&<button className="text-button" onClick={()=>downloadFile(`/api/tenants/${tenant}/files/${s.data.fileId}`,token,s.data.title).catch(e=>setError(e.message))}>Arquivo <ArrowDownToLine size={13}/></button>}</div></article>)}</div>{!rows.length&&<Blank icon={FolderOpen} title="Nenhuma fonte encontrada">Adicione texto, notícia, PDF ou uma referência acompanhada do material acessível.</Blank>}</>;}

type Api=<T>(path:string,body?:unknown,method?:string)=>Promise<T>;
type Action=(fn:()=>Promise<unknown>,message?:string)=>Promise<void>;
function Trends({data,api,action,canEdit,canAdmin,busy,edit,suggest}:{suggest:(source:SuggestedTrendSource)=>void;data:Dataset;api:Api;action:Action;canEdit:boolean;canAdmin:boolean;busy:boolean;edit:(v:RecordRow<PostData>)=>void}){const [tab,setTab]=useState('opportunities');const [selected,setSelected]=useState<string|null>(null);const topic=data.trends.find(t=>t.id===selected);return <><div className="trends-intro"><div><span className="eyebrow">INTELIGÊNCIA EDITORIAL</span><h2>Recência não é tendência.<br/>O contexto faz a diferença.</h2><p>Oportunidades são acompanhadas por fontes e observações. Crescimento exige histórico comparável.</p></div><div className="trends-stats"><div><strong>{data.trendSources.length}</strong><span>fontes configuradas</span></div><div><strong>{data.trendItems.length}</strong><span>itens descobertos</span></div><div><strong>{data.trends.length}</strong><span>pautas classificadas</span></div></div></div><div className="tabs" role="tablist" aria-label="Radar">{[['opportunities','Oportunidades'],['suggestions','Fontes sugeridas'],['sources','Fontes monitoradas'],['items','Extrações e histórico']].map(([k,v])=><button role="tab" aria-selected={tab===k} className={tab===k?'active':''} key={k} onClick={()=>setTab(k)}>{v}</button>)}</div>
  {tab==='opportunities'&&<div className="trend-grid">{data.trends.map(t=><article className="panel trend-card" key={t.id}><div className="row-between"><Badge tone="success">{stateLabel(t.data.state??t.data.signal)}</Badge><span className="micro">{dateLabel(t.updatedAt,data.workspace.timezone,true)}</span></div><h2>{text(t.data.title,text(t.data.topic,'Oportunidade editorial'))}</h2><p>{text(t.data.reason,text(t.data.summary,'Consulte as evidências antes de criar.'))}</p><div className="signal-grid">{[['Relevância',t.data.relevance??t.data.relevanceScore],['Intensidade',t.data.intensity??t.data.signalScore],['Confiança',t.data.confidence??t.data.confidenceScore]].map(([k,v])=><div key={text(k)}><small>{text(k)}</small><strong>{text(v,'Indisponível')}</strong></div>)}</div><button className="text-button" onClick={()=>setSelected(t.id)}>Evidências e histórico <ArrowRight size={15}/></button><div className="card-actions"><button disabled={!canEdit||busy} onClick={()=>void action(()=>api(`trends/${t.id}/decision`,{action:'save'}),'Oportunidade salva.')}><BookOpen size={15}/> Salvar</button><button disabled={!canEdit||busy} className="primary" onClick={()=>void action(async()=>{const r=await api<{post?:RecordRow<PostData>}>(`trends/${t.id}/decision`,{action:'create_post'});if(r.post)edit(r.post);},'Rascunho criado a partir da pauta.')}><Plus size={15}/> Criar post</button><button className="icon" disabled={!canEdit||busy} aria-label="Descartar oportunidade" onClick={()=>void action(()=>api(`trends/${t.id}/decision`,{action:'discard'}),'Oportunidade descartada.')}><X size={16}/></button></div></article>)}</div>}
  {tab==='opportunities'&&!data.trends.length&&<Blank icon={Flame} title="Seu radar está começando">Configure fontes e acompanhe as primeiras coletas. O sistema distingue oportunidade recente de crescimento comprovado.</Blank>}
  {tab==='suggestions'&&<SourceSuggestions urls={data.trendSources.map(source=>text(source.data.url,''))} canAdd={canEdit&&data.trendSources.length<30} busy={busy} select={suggest}/>}
  {tab==='sources'&&<Section title="Coleta recorrente" subtitle="Ative, pause e acompanhe o acesso de cada origem">{data.trendSources.map(s=><div className="monitor-row" key={s.id}><span className="source-icon"><Globe2 size={20}/></span><div className="grow"><strong>{text(s.data.name,'Fonte monitorada')}</strong><small className="wrap">{text(s.data.url)}</small><small>Última coleta: {s.data.lastCollectedAt?dateLabel(text(s.data.lastCollectedAt),data.workspace.timezone,true):'Ainda não coletada'} · Próxima: {s.data.nextRunAt?dateLabel(text(s.data.nextRunAt),data.workspace.timezone,true):'Aguardando fila'}</small>{Boolean(s.data.lastError)&&<small className="danger-text">{text(s.data.lastError)}</small>}<span className="micro">{arr(s.data.keywords).map(v=>text(v)).join(', ')} · {text(s.data.language)} · {text(s.data.region)}</span></div><Badge tone={s.data.enabled===false?'neutral':'success'}>{s.data.enabled===false?'Pausada':'Ativa'}</Badge><button disabled={!canAdmin||busy} onClick={()=>void action(()=>api(`trend-sources/${s.id}/collect`),'Coleta adicionada à fila.')}><RefreshCw size={15}/> Coletar</button><button disabled={!canAdmin||busy} onClick={()=>void action(()=>api(`trend-sources/${s.id}`,{revision:s.revision,enabled:s.data.enabled===false},'PATCH'),'Monitoramento atualizado.')}>{s.data.enabled===false?'Retomar':'Pausar'}</button></div>)}{!data.trendSources.length&&<Blank icon={Link2} title="Escolha suas primeiras origens">Comece com RSS/Atom e páginas públicas permitidas. As coletas respeitam acesso, frequência e limites.</Blank>}</Section>}
  {tab==='items'&&<Section title="Materiais descobertos" subtitle="Texto extraído, metadados e falhas identificados separadamente">{data.trendItems.map(item=><details key={item.id} className="extraction"><summary><span>{text(item.data.title,'Item descoberto')}</span><Badge tone={item.data.extractionState==='extracted'?'success':'neutral'}>{stateLabel(item.data.extractionState??item.data.state)}</Badge></summary><p>{text(item.data.text,text(item.data.excerpt,'Conteúdo textual indisponível.'))}</p><p className="micro">Origem: {text(item.data.url)} · {dateLabel(item.createdAt,data.workspace.timezone,true)}</p>{Boolean(item.data.error)&&<p className="danger-text">{text(item.data.error)}</p>}<pre>{JSON.stringify(item.data,null,2)}</pre></details>)}{!data.trendItems.length&&<p className="muted">Nenhuma extração registrada. Os resultados aparecerão após as coletas.</p>}</Section>}
  {topic&&<Modal title="Evidências da oportunidade" close={()=>setSelected(null)}><h3>{text(topic.data.title,text(topic.data.topic))}</h3><p>{text(topic.data.reason)}</p><p className="micro">Origem, cobertura, observações e versão do ranking conforme disponíveis. Pontuação não é probabilidade de viralização.</p><pre>{JSON.stringify(topic.data,null,2)}</pre></Modal>}</>;}

function Analytics({data,range,network,token}:{data:Dataset;range:number;network:string;token:string}){const metrics=latestMetrics(data,range,network);const [error,setError]=useState('');const [sortMetric,setSortMetric]=useState('views');const ranked=[...metrics].sort((a,b)=>(num(b.data[sortMetric])??num(obj(b.data.values??b.data.metrics)[sortMetric])??-1)-(num(a.data[sortMetric])??num(obj(a.data.values??a.data.metrics)[sortMetric])??-1));const fields=['reach','views','likes','comments','saves','shares'];const names:Record<string,string>={reach:'Alcance',views:'Visualizações',likes:'Curtidas',comments:'Comentários',saves:'Salvamentos',shares:'Compartilhamentos'};function csv(){const rows=[['Registro','Publicação','Rede','Métrica','Valor','Unidade','Janela','Observado em',...fields],...metrics.map(r=>[r.id,text(r.data.publicationId),text(r.data.platform),text(r.data.metric),text(r.data.value,''),text(r.data.unit),text(r.data.window),text(r.data.observedAt,r.createdAt),...fields.map(k=>{const n=num(r.data[k])??num(obj(r.data.values??r.data.metrics)[k]);return n===null?'':String(n);})])];const safe=(v:string)=>`"${(/^[=+@\-\t\r]/.test(v)?"'":'')+v.replaceAll('"','""')}"`;const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='socialengine-resultados.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
return <><div className="metric-grid">{fields.slice(0,4).map(k=><div className="metric-card" key={k}><span>{names[k]}</span><strong>{numeric(aggregate(metrics,k))}</strong><small>Último snapshot por publicação no período</small></div>)}</div><Section title="Histórico disponível" subtitle="Métricas acumuladas usam o último snapshot por publicação, unidade e janela." action={<button disabled={!metrics.length} onClick={csv}><ArrowDownToLine size={16}/> Exportar CSV</button>}><p className="micro">Alcance somado não representa pessoas únicas entre posts ou redes. Células vazias no CSV são valores indisponíveis.</p>{error&&<p role="alert">{error}</p>}{metrics.length?<><div className="list-filters"><label>Ordenar por<select value={sortMetric} onChange={e=>setSortMetric(e.target.value)}>{fields.map(k=><option value={k} key={k}>{names[k]}</option>)}</select></label></div><div className="table-scroll"><table><thead><tr><th>Publicação / origem</th><th>Rede</th>{fields.map(k=><th key={k}>{names[k]}</th>)}<th>Observação</th></tr></thead><tbody>{ranked.map(r=><tr key={r.id}><td>{text(r.data.title,text(r.data.publicationId,r.id.slice(0,8)))}</td><td>{text(r.data.platform)}</td>{fields.map(k=><td key={k}>{numeric(num(r.data[k])??num(obj(r.data.values??r.data.metrics)[k])??(r.data.metric===k?num(r.data.value):null))}</td>)}<td>{dateLabel(text(r.data.observedAt,r.createdAt),data.workspace.timezone,true)}</td></tr>)}</tbody></table></div><div className="bar-chart" aria-label={`Comparação por ${names[sortMetric]}`}>{ranked.slice(0,8).map(r=>{const value=num(r.data[sortMetric])??num(obj(r.data.values??r.data.metrics)[sortMetric]);const max=Math.max(1,...ranked.map(v=>num(v.data[sortMetric])??num(obj(v.data.values??v.data.metrics)[sortMetric])??0));return <div key={r.id}><span>{text(r.data.title,text(r.data.publicationId,r.id.slice(0,8)))}</span><div><i style={{width:`${value===null?0:Math.max(1,value/max*100)}%`}}/></div><strong>{numeric(value)}</strong></div>;})}</div></>:<Blank icon={BarChart3} title="Resultados precisam de dados reais">As redes conectadas alimentarão este histórico. Ausência de integração ou de coleta não é resultado zero.</Blank>}</Section><Section title="Campanhas e distribuição" subtitle="Acompanhamento separado por destino">{data.campaigns.map(c=><details key={c.id} className="extraction"><summary>{text(c.data.title,'Campanha')}</summary><pre>{JSON.stringify(c.data,null,2)}</pre></details>)}{!data.campaigns.length&&<p className="muted">Nenhuma campanha registrada.</p>}</Section></>;}

function Calendar({data,api,action,edit,canPublish}:{data:Dataset;api:Api;action:Action;edit:(p:RecordRow<PostData>)=>void;canPublish:boolean}){const [month,setMonth]=useState(()=>new Date());const year=month.getFullYear(),m=month.getMonth();const first=new Date(year,m,1).getDay(),count=new Date(year,m+1,0).getDate();const key=(date:string)=>{const d=new Date(date);return Number.isNaN(d.getTime())?'':new Intl.DateTimeFormat('en-CA',{timeZone:data.workspace.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(d);};return <><Section title={month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})} subtitle={`Planejamento e execução · ${data.workspace.timezone}`} action={<div className="row"><button className="icon" aria-label="Mês anterior" onClick={()=>setMonth(new Date(year,m-1,1))}><ChevronLeft size={18}/></button><button onClick={()=>setMonth(new Date())}>Hoje</button><button className="icon" aria-label="Próximo mês" onClick={()=>setMonth(new Date(year,m+1,1))}><ChevronRight size={18}/></button></div>}><div className="calendar-scroll"><div className="calendar-grid">{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d=><strong className="weekday" key={d}>{d}</strong>)}{Array.from({length:first},(_,i)=><div className="calendar-day outside" key={`out-${i}`}/>)}{Array.from({length:count},(_,i)=>{const day=i+1;const stamp=`${year}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const jobs=data.jobs.filter(j=>key(j.runAt)===stamp);const plans=data.posts.filter(p=>p.data.plannedAt&&key(p.data.plannedAt)===stamp);return <div className={`calendar-day ${stamp===key(new Date().toISOString())?'today':''}`} key={day}><span>{day}</span>{plans.map(p=><button key={p.id} onClick={()=>edit(p)}><i className="plan-dot"/>{p.data.title}<small>Planejado</small></button>)}{jobs.map(j=><div className={`calendar-event ${j.state}`} key={j.id}><Clock3 size={11}/>{text(obj(j.payload).title,j.type)}<small>{stateLabel(j.state)}</small></div>)}</div>;})}</div></div></Section><Section title="Fila e resultados por destino" subtitle="Cancelar interrompe novos envios elegíveis. Estados incertos exigem reconciliação.">{data.jobs.map(j=><div key={j.id} className="monitor-row"><Clock3 size={20}/><div className="grow"><strong>{text(obj(j.payload).title,j.type)}</strong><small>{dateLabel(j.runAt,data.workspace.timezone,true)} · Tentativas: {j.attempts}</small>{j.lastError&&<small className="danger-text">{j.lastError}</small>}</div><Badge tone={j.state==='succeeded'?'success':['failed','uncertain'].includes(j.state)?'warning':'neutral'}>{stateLabel(j.state)}</Badge>{j.state==='queued'&&<button disabled={!canPublish} onClick={()=>void action(()=>api(`jobs/${j.id}/cancel`),'Trabalho cancelado.')}>Cancelar</button>}</div>)}{!data.jobs.length&&<p className="muted">Nenhum trabalho na fila.</p>}{data.publications.map(p=><div className="activity" key={p.id}><CheckCircle2 size={18}/><div><strong>{text(p.data.platform)} · {stateLabel(p.data.state??p.data.status)}</strong><small>{text(p.data.error,'')}</small>{typeof p.data.url==='string'&&/^https?:\/\//i.test(p.data.url)&&<a href={p.data.url} target="_blank" rel="noreferrer">Abrir publicação <ExternalLink size={12}/></a>}</div></div>)}</Section></>;}

function WorkspaceForm({submit,busy,workspace}:{submit:(values:typeof defaults)=>Promise<void>;busy:boolean;workspace?:Workspace}){const [v,setV]=useState(workspace?{name:workspace.name,niche:workspace.niche,audience:workspace.audience,objectives:workspace.objectives,timezone:workspace.timezone,brand:workspace.brand,blog:workspace.blog}:structuredClone(defaults));const field=(key:'name'|'niche'|'audience'|'objectives'|'timezone',value:string)=>setV({...v,[key]:value});return <form onSubmit={e=>{e.preventDefault();void submit(v);}}><div className="form-grid"><label>Nome do influenciador<input required minLength={2} maxLength={100} value={v.name} onChange={e=>field('name',e.target.value)}/></label><label>Nicho principal<input required value={v.niche} onChange={e=>field('niche',e.target.value)} placeholder="Ex.: finanças pessoais"/></label></div><label>Público<textarea value={v.audience} onChange={e=>field('audience',e.target.value)} placeholder="Para quem este influenciador cria conteúdo?"/></label><label>Objetivos<textarea value={v.objectives} onChange={e=>field('objectives',e.target.value)}/></label><div className="form-grid"><label>Cor da marca<input type="color" value={v.brand.color} onChange={e=>setV({...v,brand:{...v.brand,color:e.target.value}})}/></label><label>Fuso horário<input required value={v.timezone} onChange={e=>field('timezone',e.target.value)} placeholder="America/Sao_Paulo"/></label></div><label>Tom de voz<textarea value={v.brand.voice} onChange={e=>setV({...v,brand:{...v.brand,voice:e.target.value}})} placeholder="Ex.: direto, acolhedor, com exemplos práticos"/></label><BlogFields value={v.blog} change={blog=>setV({...v,blog})}/><div className="form-actions"><button className="primary" disabled={busy}>{busy?<LoaderCircle className="spin" size={16}/>:<Check size={16}/>} Salvar influenciador</button></div></form>;}
function BlogFields({value,change}:{value:Blog;change:(v:Blog)=>void}){const field=(k:keyof Blog,v:string)=>change({...value,[k]:v});return <fieldset><legend><Globe2 size={16}/> Blog do influenciador</legend><p className="micro">Cadastro para uso futuro. Salvar o blog não inicia coleta nem autoriza publicação.</p><div className="form-grid"><label>Estado<select value={value.status} onChange={e=>field('status',e.target.value)}><option value="undefined">A definir</option><option value="provisioning">Em implantação</option><option value="active">Ativo</option><option value="inactive">Inativo</option></select></label><label>Plataforma / CMS<input value={value.platform} onChange={e=>field('platform',e.target.value)} placeholder="Ainda não definido"/></label></div><label>URL principal<input type="url" required={value.status==='active'} pattern="https?://.*" value={value.url} onChange={e=>field('url',e.target.value)} placeholder="https://seublog.com"/></label><div className="form-grid"><label>Feed RSS/Atom<input type="url" pattern="https?://.*" value={value.feedUrl} onChange={e=>field('feedUrl',e.target.value)} placeholder="Opcional"/></label><label>Idioma<input value={value.language} onChange={e=>field('language',e.target.value)}/></label></div><small className="muted">Integração: {stateLabel(value.integrationState)}</small></fieldset>;}

function SourceForm({busy,submit}:{busy:boolean;submit:(v:SourceData,file:File|null)=>Promise<void>}){const [kind,setKind]=useState<SourceData['kind']>('text');const [file,setFile]=useState<File|null>(null);return <form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const content=String(f.get('text')??'');void submit({title:String(f.get('title')),kind,url:String(f.get('url')??'')||undefined,text:content,extractionState:content?'extracted':file?'pending':'metadata_only'},file);}}><label>Título<input name="title" required/></label><label>Tipo<select value={kind} onChange={e=>setKind(e.target.value as SourceData['kind'])}><option value="text">Texto</option><option value="news">Notícia / artigo</option><option value="pdf">PDF</option><option value="youtube">YouTube + transcrição</option><option value="instagram">Reel / carrossel de referência</option><option value="video">Vídeo enviado</option></select></label><label>URL da origem<input name="url" type="url" pattern="https?://.*" placeholder="https://…"/></label><label>Texto ou transcrição<textarea name="text" rows={7} required={kind==='text'} placeholder="Cole o conteúdo acessível. Um link não garante leitura ou transcrição automática."/></label><label className="upload"><Upload size={19}/> Arquivo opcional<input type="file" accept=".pdf,.txt,image/*,video/*,audio/*" onChange={e=>setFile(e.target.files?.[0]??null)}/><small>{file?.name??'PDF, imagem ou material autorizado'}</small></label><p className="micro">A referência é tratada como material-fonte. Instruções dentro dela não comandam o sistema.</p><button className="primary" disabled={busy}><Plus size={16}/> Adicionar à biblioteca</button></form>;}
function TrendSourceForm({busy,submit,initial}:{initial?:SuggestedTrendSource|null;busy:boolean;submit:(v:Record<string,unknown>)=>Promise<void>}){return <form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const words=(name:string)=>String(f.get(name)??'').split(',').map(s=>s.trim()).filter(Boolean);void submit({name:f.get('name'),url:f.get('url'),type:f.get('type'),keywords:words('keywords'),exclusions:words('exclusions'),language:f.get('language'),region:f.get('region'),intervalMinutes:Number(f.get('intervalMinutes')),enabled:true,accessAcknowledged:f.get('accessAcknowledged')==='on'});}}><>{initial&&<div className="suggestion-review"><strong>{initial.name}</strong><p>{initial.description}</p><p className="micro">{initial.accessNote}</p><a href={initial.referenceUrl} target="_blank" rel="noreferrer">Consultar condições do editor ↗</a><p className="micro">Ajuste os termos em inglês ao nicho do influenciador antes de confirmar.</p></div>}<label>Nome da fonte<input name="name" defaultValue={initial?.name} required/></label><label>Endereço público<input name="url" type="url" defaultValue={initial?.url} pattern="https?://.*" required placeholder="https://…"/></label><label>Conector<select name="type" defaultValue={initial?.type??'rss'}><option value="rss">Feed RSS / Atom</option><option value="html">Página pública HTML</option></select></label><label>Palavras-chave<input name="keywords" defaultValue={initial?.keywords.join(', ')} required placeholder="Separe por vírgulas"/></label><label>Exclusões<input name="exclusions" placeholder="Termos que não devem aparecer"/></label><div className="form-grid"><label>Idioma<input name="language" defaultValue={initial?.language??'pt-BR'} required/></label><label>Região<input name="region" defaultValue={initial?.region??'BR'} required/></label></div><label>Intervalo entre coletas (minutos)<input name="intervalMinutes" type="number" min="30" max="10080" defaultValue={initial?.intervalMinutes??120} required/></label><p className="micro">A coleta respeita políticas da origem, endereços públicos e cotas. Acesso bloqueado será identificado, sem contornar login ou paywall.</p><label className="checkbox access-ack"><input name="accessAcknowledged" type="checkbox" required/>Confirmei as condições de acesso e reutilização desta fonte.</label><button disabled={busy} className="primary"><Flame size={16}/> Iniciar monitoramento</button></></form>;}

function Settings({workspace,data,api,action,busy,admin}:{workspace:Workspace;data:Dataset;api:Api;action:Action;busy:boolean;admin:boolean}){const [tab,setTab]=useState('brand');const [provider,setProvider]=useState('openai');const [apiKey,setApiKey]=useState('');const [confirm,setConfirm]=useState<{kind:'credential'|'account';id:string}|null>(null);return <><div className="tabs" role="tablist" aria-label="Configurações">{[['brand','Marca e blog'],['accounts','Contas sociais'],['apis','APIs e consumo'],['team','Equipe e acesso']].map(([k,v])=><button role="tab" aria-selected={tab===k} className={tab===k?'active':''} key={k} onClick={()=>setTab(k)}>{v}</button>)}</div>{!admin&&<p className="pending">Você pode consultar este espaço. Alterações de configuração exigem permissão de administrador.</p>}
{tab==='brand'&&<Section title="Identidade do influenciador" subtitle="Essas preferências acompanham a criação de cada conteúdo."><fieldset className="unframed" disabled={!admin||busy}><WorkspaceForm workspace={workspace} busy={busy} submit={v=>action(()=>api('settings',v,'PATCH'),'Identidade e blog atualizados.')}/></fieldset></Section>}
{tab==='accounts'&&<><div className="connection-grid">{platforms.map(p=>{const accounts=data.accounts.filter(a=>a.data.platform===p);return <Section key={p} title={platformNames[p]} action={<Network name={p}/>}>{accounts.map(a=><div className="account" key={a.id}><strong>{text(a.data.handle,text(a.data.name,text(a.data.username,'Conta autorizada')))}</strong><Badge tone={a.data.state==='connected'?'success':'warning'}>{stateLabel(a.data.state)}</Badge><small>{text(a.data.providerId,text(a.data.externalId,''))}</small><button className="danger-button" disabled={!admin||busy} onClick={()=>setConfirm({kind:'account',id:a.id})}>Desconectar</button></div>)}{!accounts.length&&<p className="muted">Nenhuma conta conectada. A autorização acontece na rede social.</p>}<button disabled={!admin||busy} onClick={()=>void action(async()=>{const r=await api<{authorizationUrl:string}>(`accounts/${p}/connect`,undefined,'GET');const url=new URL(r.authorizationUrl);if(url.protocol!=='https:')throw new Error('Endereço de autorização inválido.');window.location.assign(url.href);},'Redirecionando para autorização…')}><Link2 size={15}/> {accounts.length?'Autorizar outra conta':'Conectar conta'}</button></Section>;})}</div><p className="micro">As capacidades dependem do aplicativo e das permissões concedidas por cada rede. Desconectar impede novos envios; o histórico permanece.</p></>}
{tab==='apis'&&<><AiPreferences workspace={workspace} api={api} action={action} disabled={!admin||busy}/><Section title="Provedores de inteligência artificial" subtitle="Substitua ou revogue suas chaves. Segredos salvos nunca são recuperados pela interface."><fieldset className="unframed" disabled={!admin||busy}><form onSubmit={e=>{e.preventDefault();void action(async()=>{await api('credentials',{provider,key:apiKey});setApiKey('');},'Credencial protegida no servidor.');}}><div className="form-grid"><label>Provedor<select value={provider} onChange={e=>setProvider(e.target.value)}><option value="openai">OpenAI</option><option value="anthropic">Anthropic</option></select></label><label>Chave própria<input type="password" value={apiKey} onChange={e=>setApiKey(e.target.value)} required autoComplete="off" spellCheck={false} placeholder="Cole uma nova chave"/></label></div><button className="primary"><ShieldCheck size={16}/> Salvar / substituir chave</button></form></fieldset>{data.credentials.map(c=><div className="monitor-row" key={c.id}><ShieldCheck size={19}/><div className="grow"><strong>{c.provider}</strong><small>{c.maskedHint} · {stateLabel(c.state)}</small></div><button disabled={!admin||busy} onClick={()=>void action(()=>api(`credentials/${c.id}/test`),'Teste de conexão finalizado.')}>Testar conexão</button><button className="danger-button" disabled={!admin||busy} onClick={()=>setConfirm({kind:'credential',id:c.id})}>Revogar</button></div>)}{!data.credentials.length&&<p className="muted">Nenhuma chave própria cadastrada. A integração da plataforma depende da configuração do servidor.</p>}</Section><Section title="Consumo e capacidades" subtitle="Consumo observado por geração e capacidades informadas pelo servidor."><div className="table-scroll"><table><thead><tr><th>Provedor / modelo</th><th>Consumo</th><th>Estado</th><th>Quando</th></tr></thead><tbody>{data.usage.map(u=><tr key={u.id}><td>{text(u.data.provider)} / {text(u.data.model)}</td><td>{numeric(num(u.data.totalTokens)??num(u.data.tokens))} tokens</td><td>{stateLabel(u.data.state??u.data.status)}</td><td>{dateLabel(u.createdAt,workspace.timezone,true)}</td></tr>)}</tbody></table></div>{!data.usage.length&&<p className="muted">Consumo ainda indisponível. Não representa saldo ou custo zero.</p>}<details className="extraction"><summary>Capacidades e limites disponíveis</summary><pre>{JSON.stringify(data.capabilities,null,2)}</pre></details></Section></>}
{tab==='team'&&<Section title="Equipe do influenciador" subtitle="Papéis podem ser acumulados. A autorização é validada no servidor."><fieldset className="unframed" disabled={!admin||busy}><form onSubmit={e=>{e.preventDefault();const form=e.currentTarget;const f=new FormData(form);void action(async()=>{await api('members',{userId:String(f.get('userId')),roles:f.getAll('roles')});form.reset();},'Vínculo de equipe atualizado.');}}><label>ID do usuário autenticado<input name="userId" required placeholder="Identificador da conta na plataforma"/></label><fieldset><legend>Permissões</legend><div className="role-options">{roles.map(r=><label className="checkbox" key={r}><input name="roles" type="checkbox" value={r}/>{roleNames[r]}</label>)}</div></fieldset><p className="micro">Para revogar um vínculo, envie os papéis vazios para o usuário correspondente.</p><button className="primary"><Users size={16}/> Atualizar acesso</button></form></fieldset><div className="members">{data.members.map(m=><div className="monitor-row" key={m.userId}><span className="mini-avatar"><Users size={17}/></span><div className="grow"><strong className="wrap">{m.userId}</strong><small>{m.roles.map(r=>roleNames[r]).join(' · ')||'Sem acesso'}</small></div><button disabled={!admin||busy} className="danger-button" onClick={()=>void action(()=>api('members',{userId:m.userId,roles:[]}),'Vínculo revogado.')}>Revogar</button></div>)}</div></Section>}
{confirm&&<Modal title={confirm.kind==='credential'?'Revogar credencial?':'Desconectar conta?'} close={()=>setConfirm(null)}><p>Novos usos desta conexão serão bloqueados. Trabalhos pendentes podem precisar de revisão. O histórico será preservado.</p><div className="form-actions"><button onClick={()=>setConfirm(null)}>Voltar</button><button className="danger-button" disabled={busy} onClick={()=>void action(async()=>{await api(`${confirm.kind==='credential'?'credentials':'accounts'}/${confirm.id}`,undefined,'DELETE');setConfirm(null);},'Conexão revogada.')}>Confirmar</button></div></Modal>}</>;}

function aiValue(workspace:Workspace){return obj((workspace as Workspace&{ai?:unknown}).ai);}
function hasModel(workspace:Workspace){const ai=aiValue(workspace);return ai.provider==='openai'&&typeof ai.model==='string'&&ai.model.trim().length>0;}
function AiPreferences({workspace,api,action,disabled}:{workspace:Workspace;api:Api;action:Action;disabled:boolean}){
  const initial=aiValue(workspace);const [provider,setProvider]=useState(text(initial.provider,'openai')),[model,setModel]=useState(text(initial.model,'')),[monthlyRequests,setMonthlyRequests]=useState(num(initial.monthlyRequests)??100);
  return <Section title="Modelo e cota de geração" subtitle="Defina explicitamente o modelo e o limite mensal deste influenciador."><fieldset className="unframed" disabled={disabled}><form onSubmit={e=>{e.preventDefault();void action(()=>api('settings',{name:workspace.name,niche:workspace.niche,audience:workspace.audience,objectives:workspace.objectives,timezone:workspace.timezone,brand:workspace.brand,blog:workspace.blog,ai:{provider,model:model.trim(),monthlyRequests}},'PATCH'),'Modelo e cota de IA atualizados.');}}><div className="form-grid"><label>Provedor de geração<select value={provider} onChange={e=>setProvider(e.target.value)}><option value="openai">OpenAI</option><option value="anthropic" disabled>Anthropic · geração pendente</option></select></label><label>Identificador do modelo<input required value={model} maxLength={120} onChange={e=>setModel(e.target.value)} placeholder="Modelo habilitado na sua conta do provedor"/></label></div><label>Limite de solicitações por mês<input type="number" min="0" max="100000" required value={monthlyRequests} onChange={e=>setMonthlyRequests(Number(e.target.value))}/><small>O servidor aplica o teto da plataforma. Aumentar este campo não concede uma cota acima dele.</small></label><button className="primary"><Check size={16}/> Salvar preferências de IA</button></form></fieldset><p className="micro">Disponibilidade do modelo e credencial são confirmadas pelo provedor na chamada. O consumo é atribuído a este espaço.</p></Section>;
}
function Editor({row,data,busy,canEdit,canReview,canPublish,token,api,action,save,review,update}:{row:RecordRow<PostData>;data:Dataset;busy:boolean;canEdit:boolean;canReview:boolean;canPublish:boolean;token:string;api:Api;action:Action;save:(r:RecordRow<PostData>)=>Promise<RecordRow<PostData>>;review:(r:RecordRow<PostData>,decision:'submit'|'approve'|'request_changes',comment?:string)=>Promise<void>;update:(r:RecordRow<PostData>)=>void}){
  const [draft,setDraft]=useState<PostData>(structuredClone(row.data)),[slide,setSlide]=useState(0),[dirty,setDirty]=useState(false),[localBusy,setLocalBusy]=useState(false),[localError,setLocalError]=useState(''),[comment,setComment]=useState(''),[accountIds,setAccountIds]=useState<string[]>([]),[schedule,setSchedule]=useState(''),[confirmPublish,setConfirmPublish]=useState(false);
  useEffect(()=>{setDraft(structuredClone(row.data));setDirty(false);},[row.revision]);
  const editing=canEdit&&!localBusy&&!busy;const current=draft.slides[slide];const changed=(next:PostData)=>{setDraft(next);setDirty(true);};const field=<K extends keyof PostData>(k:K,v:PostData[K])=>changed({...draft,[k]:v});
  const changeSlide=(key:'title'|'body',value:string)=>field('slides',draft.slides.map((s,i)=>i===slide?{...s,[key]:value}:s));
  async function saveCurrent(){setLocalBusy(true);setLocalError('');try{const saved=await save({...row,data:draft});setDraft(structuredClone(saved.data));setDirty(false);return saved;}catch(e){setLocalError((e as Error).message);return null;}finally{setLocalBusy(false);}}
  const postPath=`/api/tenants/${data.workspace.id}/posts/${row.id}`;const exportAction=(format:'png'|'json'|'video')=>{setLocalError('');setLocalBusy(true);downloadFile(`${postPath}/export?format=${format}&slide=${slide}`,token,`${draft.title||'socialengine'}${format==='png'?`-${slide+1}`:''}.${format==='video'?'mp4':format}`).catch(e=>setLocalError(e.message)).finally(()=>setLocalBusy(false));};
  return <div className="editor"><div className="editor-status"><PostStatus status={row.data.status}/><span>Revisão {row.revision||'inicial'}{dirty?' · alterações não salvas':''}</span><small>Editar uma versão aprovada exige nova revisão.</small></div>{localError&&<div className="alert" role="alert">{localError}</div>}{row.data.reviewComment&&<p className="pending">Revisão: {row.data.reviewComment}</p>}
    <div className="editor-layout"><div className="editor-preview"><div className="slide-preview" style={{background:draft.color}}><div className="preview-label">{data.workspace.name} <span>{slide+1}/{draft.slides.length}</span></div><>{current?.imageFileId&&<PrivateImage token={token} tenant={data.workspace.id} id={current.imageFileId}/>}<h2>{current?.title||'Uma boa história começa aqui.'}</h2></><p>{current?.body||'Escolha suas palavras. Encontre a sua perspectiva.'}</p><div className="preview-footer">{data.workspace.niche}<ArrowRight size={24}/></div></div><p className="micro">Prévia editorial de texto e composição. A exportação é renderizada no servidor.</p><div className="slide-strip">{draft.slides.map((s,i)=><button key={s.id} className={slide===i?'selected':''} onClick={()=>setSlide(i)} aria-label={`Editar slide ${i+1}`} style={{background:draft.color}}>{i+1}</button>)}<button disabled={!editing||draft.slides.length>=12} aria-label="Adicionar slide" onClick={()=>{field('slides',[...draft.slides,{id:crypto.randomUUID(),title:'',body:''}]);setSlide(draft.slides.length);}}><Plus size={17}/></button></div><div className="row"><button disabled={!editing||slide===0} onClick={()=>{const slides=[...draft.slides];[slides[slide-1],slides[slide]]=[slides[slide],slides[slide-1]];field('slides',slides);setSlide(slide-1);}}><ChevronLeft size={15}/> Mover</button><button disabled={!editing||slide>=draft.slides.length-1} onClick={()=>{const slides=[...draft.slides];[slides[slide+1],slides[slide]]=[slides[slide],slides[slide+1]];field('slides',slides);setSlide(slide+1);}}>Mover <ChevronRight size={15}/></button><button className="icon danger-button" aria-label="Remover slide" disabled={!editing||draft.slides.length<=1} onClick={()=>{field('slides',draft.slides.filter((_,i)=>i!==slide));setSlide(Math.max(0,slide-1));}}><Trash2 size={16}/></button></div></div>
    <div className="editor-fields"><fieldset disabled={!editing} className="unframed"><label>Título do conteúdo<input required maxLength={200} value={draft.title} onChange={e=>field('title',e.target.value)}/></label><div className="form-grid"><label>Formato<select value={draft.format} onChange={e=>field('format',e.target.value as PostData['format'])}><option value="carousel">Carrossel</option><option value="video">Vídeo básico</option><option value="text">Texto</option></select></label><label>Cor da composição<input type="color" value={draft.color} onChange={e=>field('color',e.target.value)}/></label></div><label>Slide {slide+1} · título<input maxLength={140} value={current?.title??''} onChange={e=>changeSlide('title',e.target.value)}/></label><label>Slide {slide+1} · texto<textarea rows={4} maxLength={550} value={current?.body??''} onChange={e=>changeSlide('body',e.target.value)}/></label><label>Imagem do slide<input type="file" accept="image/*" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;setLocalBusy(true);try{const form=new FormData();form.set('file',file);const r=await request<{file:{id:string}}>(`/api/tenants/${data.workspace.id}/files`,token,{method:'POST',body:form});field('slides',draft.slides.map((s,i)=>i===slide?{...s,imageFileId:r.file.id}:s));}catch(e){setLocalError((e as Error).message);}finally{setLocalBusy(false);}}}/>{current?.imageFileId&&<small>Imagem privada vinculada ao slide.</small>}</label><label>Legenda<textarea rows={4} maxLength={4000} value={draft.caption} onChange={e=>field('caption',e.target.value)}/></label><label>Chamada para ação<input maxLength={500} value={draft.cta} onChange={e=>field('cta',e.target.value)}/></label><label>Planejamento editorial<input type="datetime-local" value={draft.plannedAt?new Date(new Date(draft.plannedAt).getTime()-new Date(draft.plannedAt).getTimezoneOffset()*60000).toISOString().slice(0,16):''} onChange={e=>field('plannedAt',e.target.value?new Date(e.target.value).toISOString():undefined)}/><small>Horário do dispositivo: {Intl.DateTimeFormat().resolvedOptions().timeZone}. O calendário exibe {data.workspace.timezone}.</small></label><fieldset><legend>Redes da versão</legend><div className="role-options">{platforms.map(p=><label className="checkbox" key={p}><input type="checkbox" checked={draft.platforms.includes(p)} onChange={e=>field('platforms',e.target.checked?[...draft.platforms,p]:draft.platforms.filter(v=>v!==p))}/>{platformNames[p]}</label>)}</div></fieldset></fieldset></div></div>
    <details className="editor-section" open><summary><Sparkles size={17}/> Fontes, inspiração e criação por IA</summary><fieldset className="unframed" disabled={!editing}><div className="form-grid"><label>Estrutura narrativa<select value={draft.structure} onChange={e=>field('structure',e.target.value)}>{structureNames.includes(draft.structure)?null:<option value={draft.structure}>{draft.structure}</option>}{structureNames.map(s=><option key={s}>{s}</option>)}</select></label><label>Referência visual / narrativa<input type="url" value={draft.referenceUrl??''} onChange={e=>field('referenceUrl',e.target.value)} placeholder="URL de inspiração"/></label></div><label>Arquivo de inspiração visual<input type="file" accept="image/*,application/pdf" disabled={!editing} onChange={async e=>{const file=e.target.files?.[0];if(!file)return;setLocalBusy(true);try{const form=new FormData();form.set('file',file);const r=await request<{file:{id:string}}>(`/api/tenants/${data.workspace.id}/files`,token,{method:'POST',body:form});field('referenceFileId',r.file.id);}catch(e){setLocalError((e as Error).message);}finally{setLocalBusy(false);}}}/>{draft.referenceFileId&&<small>Referência privada vinculada. A estrutura é inspiração para uma peça original.</small>}</label><div className="source-choices">{data.sources.map(s=><label className="checkbox" key={s.id}><input type="checkbox" checked={draft.sourceIds.includes(s.id)} onChange={e=>field('sourceIds',e.target.checked?[...draft.sourceIds,s.id]:draft.sourceIds.filter(id=>id!==s.id))}/><span>{s.data.title}<small>{stateLabel(s.data.extractionState)}</small></span></label>)}{!data.sources.length&&<p className="muted">Adicione materiais na biblioteca para gerar com base em fontes rastreáveis.</p>}</div></fieldset><div className="row wrap"><button disabled={!editing||!row.id||dirty||!draft.sourceIds.length||!hasModel(data.workspace)} onClick={()=>void action(async()=>{const r=await api<{post:RecordRow<PostData>}>('generate',{postId:row.id,revision:row.revision,sourceIds:draft.sourceIds,structure:draft.structure});update(r.post);},'Conteúdo gerado com origem e consumo registrados.')}><Sparkles size={16}/> Gerar conteúdo</button><button disabled={!editing||!row.id||dirty||!draft.sourceIds.length||!hasModel(data.workspace)} onClick={()=>void action(async()=>{const r=await api<{post:RecordRow<PostData>}>('generate',{postId:row.id,revision:row.revision,sourceIds:draft.sourceIds,structure:draft.structure,slideIndex:slide});update(r.post);},'Slide regenerado.')}><RefreshCw size={15}/> Refazer este slide</button><small className="muted">{hasModel(data.workspace)?'Salve suas alterações antes de gerar ou exportar.':'Configure provedor e modelo nas configurações de IA para habilitar a geração.'}</small></div></details>
    {draft.format==='video'&&<details className="editor-section" open><summary>Vídeo básico · cenas e áudio</summary><p className="micro">O renderizador atual suporta cenas de texto sem imagens ou áudio. Arquivos podem ser vinculados como referência para edição externa.</p><fieldset className="unframed" disabled={!editing}><div className="scene-durations">{draft.slides.map((s,i)=><label key={s.id}>Cena {i+1} (segundos)<input type="number" min="1" max="30" value={draft.video?.sceneDurations[i]??4} onChange={e=>{const sceneDurations=draft.slides.map((_,j)=>draft.video?.sceneDurations[j]??4);sceneDurations[i]=Number(e.target.value);field('video',{...draft.video,sceneDurations});}}/></label>)}</div><label>Áudio autorizado<input type="file" accept="audio/*" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;setLocalBusy(true);try{const f=new FormData();f.set('file',file);const r=await request<{file:{id:string}}>(`/api/tenants/${data.workspace.id}/files`,token,{method:'POST',body:f});field('video',{...draft.video,sceneDurations:draft.video?.sceneDurations??draft.slides.map(()=>4),audioFileId:r.file.id});}catch(e){setLocalError((e as Error).message);}finally{setLocalBusy(false);}}}/></label></fieldset><button disabled={!editing||!row.id||dirty} onClick={()=>void action(async()=>{const r=await api<{post:RecordRow<PostData>}>('videos/render',{postId:row.id,revision:row.revision});update(r.post);},'Vídeo renderizado. Revise a nova versão antes de aprovar.')}><Image size={15}/> Renderizar vídeo</button></details>}
    <div className="editor-section"><h3>Revisão e exportação</h3><div className="row wrap"><button className="primary" disabled={!editing||!draft.title.trim()} onClick={()=>void saveCurrent()}>{localBusy?<LoaderCircle size={16} className="spin"/>:<Check size={16}/>} Salvar versão</button><button disabled={!canEdit||busy||localBusy||!row.id||dirty||!['draft','changes_requested'].includes(row.data.status)} onClick={()=>void review(row,'submit')}>Enviar à revisão</button><button disabled={!canReview||busy||localBusy||!row.id||dirty||row.data.status!=='in_review'} onClick={()=>void review(row,'approve')}>Aprovar versão</button><button disabled={!row.id||dirty||busy||localBusy} onClick={()=>exportAction('png')}><ArrowDownToLine size={15}/> Slide PNG</button><button disabled={!row.id||dirty||busy||localBusy} onClick={()=>exportAction('json')}>JSON</button>{draft.video?.fileId&&<button disabled={dirty||busy||localBusy} onClick={()=>exportAction('video')}>Vídeo MP4</button>}</div>{canReview&&row.data.status==='in_review'&&<div className="review-comment"><label>Orientação para ajustes<textarea value={comment} onChange={e=>setComment(e.target.value)} placeholder="Descreva o que precisa mudar."/></label><button disabled={!comment.trim()||busy||dirty} onClick={()=>void review(row,'request_changes',comment)}>Solicitar ajustes</button></div>}</div>
    <div className="editor-section"><h3>Destinos e autorização de publicação</h3><p className="micro">Aprovação editorial e autorização de envio são distintas. Revise a versão, as contas e o horário antes de publicar.</p><div className="source-choices">{data.accounts.filter(a=>draft.platforms.includes(a.data.platform as Platform)).map(a=><label className="checkbox" key={a.id}><input type="checkbox" disabled={!canPublish||busy||dirty} checked={accountIds.includes(a.id)} onChange={e=>setAccountIds(e.target.checked?[...accountIds,a.id]:accountIds.filter(id=>id!==a.id))}/>{text(a.data.platform)} · {text(a.data.handle,text(a.data.name,text(a.data.username,'Conta')))} <Badge>{stateLabel(a.data.state)}</Badge></label>)}{!data.accounts.length&&<p className="muted">Nenhuma conta autorizada. Conecte suas contas nas configurações.</p>}</div><label>Agendar envio (opcional)<input type="datetime-local" value={schedule} onChange={e=>setSchedule(e.target.value)} disabled={!canPublish||busy||dirty}/><small>Horário do dispositivo: {Intl.DateTimeFormat().resolvedOptions().timeZone}. Deixe vazio para envio imediato.</small></label><button className="primary" disabled={!canPublish||busy||dirty||!row.id||row.data.status!=='approved'||!accountIds.length} onClick={()=>setConfirmPublish(true)}><ArrowRight size={16}/> Revisar e autorizar {schedule?'agendamento':'envio'}</button></div>
    {confirmPublish&&<Modal title="Autorizar distribuição desta versão" close={()=>setConfirmPublish(false)}><h3>{row.data.title}</h3><p>Revisão {row.revision} · {schedule?dateLabel(new Date(schedule).toISOString(),data.workspace.timezone,true):'Envio imediato'}</p><ul>{data.accounts.filter(a=>accountIds.includes(a.id)).map(a=><li key={a.id}>{text(a.data.platform)} · {text(a.data.handle,text(a.data.name,text(a.data.username,'Conta autorizada')))}</li>)}</ul><p>Você autoriza exclusivamente esta versão nos destinos acima. O resultado será acompanhado por destino.</p><div className="form-actions"><button onClick={()=>setConfirmPublish(false)}>Voltar</button><button className="primary" disabled={busy} onClick={()=>void action(async()=>{await api(`posts/${row.id}/publish`,{revision:row.revision,accountIds,scheduledAt:schedule?new Date(schedule).toISOString():undefined});setConfirmPublish(false);},'Envio autorizado e registrado na fila. Acompanhe a confirmação no calendário.')}>Autorizar distribuição</button></div></Modal>}
  </div>;
}
